const input = $input.first().json;
const row = $('Node 2 – Google Sheets Get Row').first().json;
let data = {};
if (input.choices?.[0]?.message?.content) {
  try { data = JSON.parse(input.choices[0].message.content); } catch (e) { data = {}; }
} else {
  data = { ...input };
  delete data.choices;
  delete data.row;
}
const location = data.locationTitle || data.title || row.CityOrCountry;
let version = Number(row.Version || 1);
try { if ($('Update sheet on Reject').first()) version = Number(row.Version || 1) + 1; } catch (e) {}
if (input.version) version = Number(input.version);
const mapCenter = data.mapCenter || { latitude: 48.8566, longitude: 2.3522, zoom: 12 };
const fallbackAttractions = [
  { name: location + ' City Center', description: 'Explore the downtown area.', latitude: mapCenter.latitude, longitude: mapCenter.longitude, category: 'culture' },
  { name: location + ' Historic Quarter', description: 'Historic streets and landmarks.', latitude: mapCenter.latitude + 0.01, longitude: mapCenter.longitude + 0.01, category: 'history' },
  { name: location + ' Scenic Viewpoint', description: 'Panoramic views.', latitude: mapCenter.latitude - 0.008, longitude: mapCenter.longitude + 0.012, category: 'viewpoint' }
];
let attractions = Array.isArray(data.attractions) ? data.attractions : [];
if (attractions.length < 3) attractions = [...attractions, ...fallbackAttractions].slice(0, Math.max(4, attractions.length));
attractions = attractions.map((a, i) => ({
  name: a.name || 'Attraction ' + (i + 1),
  description: a.description || 'A recommended place in ' + location,
  latitude: Number(a.latitude) || mapCenter.latitude + i * 0.005,
  longitude: Number(a.longitude) || mapCenter.longitude + i * 0.005,
  category: a.category || 'sight'
}));
const imageSearchTerms = (data.imageSearchTerms || [location + ' landmark', location + ' skyline', location + ' culture']).slice(0, 3);
const travelRecommendations = Array.isArray(data.travelRecommendations) && data.travelRecommendations.length >= 3 ? data.travelRecommendations : ['Plan ahead', 'Use public transport', 'Try local food', 'Respect customs', 'Check weather'];
const coordinates = attractions.map(a => ({ name: a.name, latitude: a.latitude, longitude: a.longitude }));
return [{ json: {
  title: data.title || location,
  locationTitle: location,
  country: data.country || '',
  introduction: data.introduction || '<p>Welcome to ' + location + '.</p>',
  travelRecommendations,
  attractions,
  imageSearchTerms,
  mapCenter,
  seoTitle: data.seoTitle || location + ' Travel Guide',
  shortSummary: data.shortSummary || 'Discover ' + location,
  coordinates,
  row,
  version,
  UserEmail: row.UserEmail,
  CityOrCountry: row.CityOrCountry,
  userComment: input.userComment || row.UserComment || ''
}}];

const data = $input.first().json;
const row = data.row || $('Node 2 – Google Sheets Get Row').first().json;
const location = data.locationTitle || data.title || row.CityOrCountry;
const version = Number(data.version || row.Version || 1);
const terms = data.imageSearchTerms || ['landmark', 'cityscape', 'culture'];
const images = terms.slice(0, 3).map(term => ({ url: 'https://source.unsplash.com/800x600/?' + encodeURIComponent(term), caption: term, alt: location + ' - ' + term }));
const center = data.mapCenter || data.attractions?.[0] || { latitude: 48.8566, longitude: 2.3522, zoom: 12 };
const lat = Number(center.latitude);
const lng = Number(center.longitude);
const zoom = center.zoom || 13;
const mapEmbedUrl = 'https://www.openstreetmap.org/export/embed.html?bbox=' + (lng - 0.08) + '%2C' + (lat - 0.05) + '%2C' + (lng + 0.08) + '%2C' + (lat + 0.05) + '&layer=mapnik&marker=' + lat + '%2C' + lng;
const mapLink = 'https://www.openstreetmap.org/?mlat=' + lat + '&mlon=' + lng + '#map=' + zoom + '/' + lat + '/' + lng;
const slug = location.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const ts = $now.toFormat('yyyy-MM-dd-HH-mm-ss');
const htmlFileName = slug + '-v' + version + '-' + ts + '.html';
const jsonFileName = slug + '-v' + version + '-' + ts + '.json';
const coordinates = (data.coordinates || data.attractions || []).map(a => ({ name: a.name, latitude: a.latitude, longitude: a.longitude }));
const metadata = { location, country: data.country, version, rowId: row.ID, cityOrCountry: row.CityOrCountry, userEmail: row.UserEmail, attractions: data.attractions, coordinates, mapCenter: center, mapLink, mapEmbedUrl, seoTitle: data.seoTitle, shortSummary: data.shortSummary, executionId: $execution.id, createdAt: row.CreatedAt || new Date().toISOString(), updatedAt: new Date().toISOString() };
return [{ json: { ...data, location, locationTitle: location, images, mapEmbedUrl, mapLink, htmlFileName, jsonFileName, htmlFilePath: 'travel-pages/' + htmlFileName, jsonFilePath: 'backups/' + jsonFileName, coordinates, metadata, version, row, UserEmail: row.UserEmail, CityOrCountry: row.CityOrCountry } }];

const data = $input.first().json;
function esc(s) { return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
const intro = data.introduction || '';
const recs = (data.travelRecommendations || []).map(r => '<li>' + esc(r) + '</li>').join('');
const attractions = data.attractions || [];
const attractionsHtml = attractions.map(a => '<article class="card"><span class="badge">' + esc(a.category) + '</span><h3>' + esc(a.name) + '</h3><p>' + esc(a.description) + '</p><p class="coords">' + a.latitude + ', ' + a.longitude + '</p></article>').join('');
const coordsRows = attractions.map(a => '<tr><td>' + esc(a.name) + '</td><td>' + a.latitude + '</td><td>' + a.longitude + '</td></tr>').join('');
const imagesHtml = (data.images || []).map((img,i) => '<figure><img src="' + esc(img.url) + '" alt="' + esc(img.alt) + '" loading="lazy"><figcaption>' + esc(img.caption) + '</figcaption></figure>').join('');
const mapEmbed = '<iframe title="Map" src="' + esc(data.mapEmbedUrl) + '" loading="lazy"></iframe>';
const hero = (data.images && data.images[0]) ? data.images[0].url : 'https://source.unsplash.com/1200x600/?travel';
const html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(data.location) + '</title><style>:root{--bg:#0f1419;--surface:#1a2332;--accent:#3d9be9;--text:#e8eef4;--muted:#94a3b8}*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif;background:var(--bg);color:var(--text);line-height:1.6}.hero{min-height:45vh;padding:3rem 1.5rem;background:linear-gradient(135deg,#1e3a5f,#0f1419),url(' + hero + ') center/cover}.container{max-width:1100px;margin:auto;padding:2rem 1.5rem}h2{border-bottom:2px solid var(--accent)}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem}.gallery img{width:100%;height:220px;object-fit:cover;border-radius:12px}.attractions{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem}.card{background:var(--surface);padding:1.25rem;border-radius:12px}iframe{width:100%;height:400px;border:0;border-radius:12px}footer{text-align:center;padding:2rem;color:var(--muted)}@media(max-width:600px){.hero{min-height:35vh}.gallery{grid-template-columns:1fr}}</style></head><body><header class="hero"><h1>' + esc(data.location) + '</h1><p>AI Travel Guide</p></header><main class="container"><section><h2>Introduction</h2>' + intro + '</section><section class="gallery"><h2>Gallery</h2>' + imagesHtml + '</section><section><h2>Recommendations</h2><ul>' + recs + '</ul></section><section><h2>Attractions</h2><div class="attractions">' + attractionsHtml + '</div></section><section><h2>Map</h2>' + mapEmbed + '<table><thead><tr><th>Place</th><th>Lat</th><th>Lng</th></tr></thead><tbody>' + coordsRows + '</tbody></table></section></main><footer><p>n8n · Groq · ' + new Date().getFullYear() + '</p></footer></body></html>';
const owner = 'REPLACE_GITHUB_OWNER';
const repo = 'REPLACE_REPO';
const githubRawUrl = 'https://raw.githubusercontent.com/' + owner + '/' + repo + '/main/' + data.htmlFilePath;
const githubPagesUrl = 'https://' + owner + '.github.io/' + repo + '/' + data.htmlFilePath;
return [{ json: { ...data, html, githubRawUrl, githubPagesUrl, metadata: { ...data.metadata, htmlLength: html.length } } }];

